# Sync source to the server so it can be built there.
#
# Why: the fat jar is ~225MB; uploading it every time is slow and fragile.
# The server has JDK21 + Node18 + Maven, so building there is much faster.
#
# What gets synced:
#   - source / config / models : always (a few MB)
#   - native libs (lib/linux64) : only with -Full (142MB, rarely changes)
#   - target / node_modules / static / sdk / docs : never
#     static is regenerated by npm build on the server; sdk is the vendor drop
#
# There is no rsync on Windows by default, so this uses a tar pipe:
#   tar czf - <dirs> | ssh 'tar xzf - -C <remote>'
#
# Usage:
#   .\sync-to-server.ps1               # incremental, source only (~5MB)
#   .\sync-to-server.ps1 -Full         # also native libs (first run)
#   .\sync-to-server.ps1 -Build        # sync then build on the server
#   .\sync-to-server.ps1 -Full -Build  # first run: full sync + build
#
# NOTE: keep this file pure ASCII. PowerShell 5.1 reads .ps1 as ANSI (GBK here)
# unless there is a BOM, so non-ASCII text gets mangled and breaks parsing.
param(
    [switch]$Full,
    [switch]$Build,
    [string]$Remote = 'root@160.202.254.65',
    [int]$Port = 10103,
    [string]$RemoteDir = '/opt/gb28181-src'
)

$ErrorActionPreference = 'Stop'
# $PSScriptRoot is <repo>\gb28181-platform-starter\scripts ; repo root is two levels up
$root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
Set-Location $root

Write-Host "repo root: $root" -ForegroundColor DarkGray
& ssh -p $Port $Remote "mkdir -p $RemoteDir"

# ---------- 1. source ----------
Write-Host '[1/3] syncing source...' -ForegroundColor Cyan

$excludes = @(
    '--exclude=target',
    '--exclude=node_modules',
    '--exclude=.git',
    '--exclude=.workbuddy',
    '--exclude=*/sdk',
    '--exclude=*/static',
    '--exclude=*/docs',
    '--exclude=*/record',
    '--exclude=*/download',
    '--exclude=*/snap',
    '--exclude=*.log'
)

# Native libs: skip entirely unless -Full. The server is Linux, win64 is never used.
if ($Full) {
    $excludes += '--exclude=*/lib/win64'
} else {
    $excludes += '--exclude=*/lib'
}

$sourceDirs = @(
    'device-access', 'gb28181-sip', 'gb28181-sip-zlm',
    'vision-api', 'vision-onnx', 'vision-pipeline',
    'models', 'sdk-dahua', 'sdk-hikvision', 'gb28181-platform-starter'
) | Where-Object { Test-Path $_ }

if ($Full) {
    Write-Host '  native libs: included (linux64)'
} else {
    Write-Host '  native libs: skipped (use -Full on first run)'
}

# Windows ships bsdtar; --exclude patterns match relative paths.
#
# IMPORTANT: do NOT pipe tar into ssh here. PowerShell's pipeline decodes native
# stdout as text, which corrupts the binary archive (tar on the far end then exits 2).
# Instead: tar to a temp file, scp it, extract remotely. Slower by one temp copy
# but reliable, and compression still keeps the transfer small.
#
# Note: ssh writes progress to stderr and $ErrorActionPreference='Stop' would turn
# that into a terminating error, so native calls run under 'Continue' and we check
# $LASTEXITCODE ourselves.
$tarArgs = @('-czf', $null) + $excludes + $sourceDirs + @('pom.xml')
$archive = Join-Path $env:TEMP 'gb28181-src.tar.gz'
Remove-Item $archive -Force -ErrorAction SilentlyContinue
$tarArgs[1] = $archive

$prevEap = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
& tar @tarArgs
$rc = $LASTEXITCODE
if ($rc -eq 0) {
    Write-Host "  archive: $([math]::Round((Get-Item $archive).Length / 1MB, 1)) MB"
    & scp -P $Port $archive "${Remote}:/tmp/gb28181-src.tar.gz"
    $rc = $LASTEXITCODE
}
if ($rc -eq 0) {
    & ssh -p $Port $Remote "tar xzf /tmp/gb28181-src.tar.gz -C $RemoteDir && rm -f /tmp/gb28181-src.tar.gz"
    $rc = $LASTEXITCODE
}
$ErrorActionPreference = $prevEap
Remove-Item $archive -Force -ErrorAction SilentlyContinue
if ($rc -ne 0) { throw "source sync failed (exit $rc)" }
Write-Host '  source synced' -ForegroundColor Green

# ---------- 2. netsdk (not on Maven Central) ----------
# com.netsdk:netsdk is a vendor jar that was installed into the local repo by hand.
# Without it the first build on the server fails, so push it into ~/.m2 directly.
Write-Host '[2/3] syncing netsdk dependency...' -ForegroundColor Cyan
$netsdk = 'D:\maven\repository\com\netsdk\netsdk\3.061'
if (Test-Path $netsdk) {
    $prevEap2 = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    # Same temp-file approach as above (no binary piping through PowerShell)
    $nArchive = Join-Path $env:TEMP 'netsdk.tar.gz'
    Remove-Item $nArchive -Force -ErrorAction SilentlyContinue
    & tar -czf $nArchive -C $netsdk .
    $rc2 = $LASTEXITCODE
    if ($rc2 -eq 0) {
        & ssh -p $Port $Remote "mkdir -p ~/.m2/repository/com/netsdk/netsdk/3.061"
        & scp -P $Port $nArchive "${Remote}:/tmp/netsdk.tar.gz"
        $rc2 = $LASTEXITCODE
    }
    if ($rc2 -eq 0) {
        & ssh -p $Port $Remote "tar xzf /tmp/netsdk.tar.gz -C ~/.m2/repository/com/netsdk/netsdk/3.061 && rm -f /tmp/netsdk.tar.gz"
        $rc2 = $LASTEXITCODE
    }
    $ErrorActionPreference = $prevEap2
    Remove-Item $nArchive -Force -ErrorAction SilentlyContinue
    if ($rc2 -ne 0) { throw "netsdk sync failed (exit $rc2)" }
    Write-Host '  netsdk synced' -ForegroundColor Green
} else {
    Write-Host "  skipped: $netsdk not found" -ForegroundColor Yellow
}

Write-Host ''
Write-Host 'sync done.' -ForegroundColor Green

if ($Build) {
    Write-Host ''
    Write-Host '[3/3] building on the server...' -ForegroundColor Cyan
    # The build logic lives in a separate .sh: PowerShell 5.1 here-strings need the
    # terminator at column 0 and write GBK by default, which makes bash choke on CRLF.
    $sh = Join-Path $PSScriptRoot 'remote-build.sh'
    if (-not (Test-Path $sh)) { throw "missing $sh" }
    & scp -P $Port $sh "${Remote}:/tmp/remote-build.sh" | Out-Null
    & ssh -p $Port $Remote "bash /tmp/remote-build.sh $RemoteDir"
}
